#!/usr/bin/env bash
set -uo pipefail
ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"; TMP="$(mktemp -d "${TMPDIR:-/tmp}/gentle-ai-rubric-gate.XXXXXX")"; trap 'rm -rf -- "$TMP"' EXIT; PASS=0; FAIL=0
put() { mkdir -p "$(dirname -- "$1")"; printf '%s\n' "$2" > "$1"; }; get() { tr -d '\n' < "$1"; }
ok() { printf 'PASS: %s\n' "$1"; PASS=$((PASS + 1)); }; no() { printf 'FAIL: %s\n' "$1" >&2; FAIL=$((FAIL + 1)); }
reject() { "$@" >/dev/null 2>&1; }
extract_block() { awk -v s="$1" -v n="$2" '$0 == ("<!-- shape:" s " -->") {a=1;next} $0 == ("<!-- /shape:" s " -->") {exit} a && $0 == ("<!-- rubric-" n ":start -->") {b=1;next} a && $0 == ("<!-- rubric-" n ":end -->") {exit} b {print}' "$ROOT/deltas/sdd-init-rubric.md" > "$3"; chmod +x "$3"; }
payload() { awk '/^  cat > "\$validator" <<\x27EOF\x27$/{p=1;next} p && /^EOF$/{exit} p{print}' "$1" > "$2"; }
load_structure_fixture() {
  export FIXTURES="$ROOT/tests/fixtures/rubric-compiler/structure" TMP_ROOT="$TMP"
  # shellcheck disable=SC1090
  source <(awk 'NR >= 6 && NR <= 29 {print}' "$ROOT/tests/rubric-compiler-structure.sh")
}
sync_facts() { local b=$1 d p; put "$b/facts/declaration/fingerprint" "$(fp "$b/facts/declaration")"; put "$b/facts/tool/fingerprint" "$(fp "$b/facts/tool")"; d="$(get "$b/facts/declaration/id")"; p="$(get "$b/facts/tool/id")"; put "$b/rows/source/fact-fingerprint" "$(fps "$b" "$d" "$p")"; put "$b/rows/default/fact-fingerprint" "$(fps "$b" "$d")"; put "$b/reinit/source/prior-fingerprint" "$(fps "$b" "$d")"; }
rebase_root() { put "$1/root" "$1/repository"; put "$1/bindings/unit/context/root" "$1/repository"; }
bundle_cnsic() {
  local b=$1 r; bundle "$b"; r="$b/repository"; cp -a "$ROOT/tests/fixtures/rubric-compiler/adapters/." "$r/"
  put "$b/observations/file/locator" AGENTS.md; put "$b/observations/file/checksum" "$(cksum "$r/AGENTS.md" | awk '{print $1 " " $2}')"
  put "$b/observations/graph/channel" file; put "$b/observations/graph/locator" requirements.txt; put "$b/observations/graph/checksum" "$(cksum "$r/requirements.txt" | awk '{print $1 " " $2}')"
  put "$b/facts/declaration/adapter" cnsic-python-v1; put "$b/facts/declaration/evidence-kind" command-declaration; put "$b/facts/tool/adapter" cnsic-python-v1; put "$b/facts/tool/evidence-kind" tool-proof; list "$b/facts/tool/observation-refs" "$(get "$b/observations/graph/id")"
  put "$b/bindings/unit/context/executable" python; put "$b/bindings/unit/context/workdir" .; put "$b/bindings/unit/method" unit; put "$b/bindings/unit/scope" path-prefix:tests/unit; put "$b/bindings/unit/signature-coverage" tests/unit; list "$b/bindings/unit/context/argv" -m pytest tests/unit/ -n auto -q; list "$b/bindings/unit/context/env"; sync_facts "$b"
}
bundle_gentle() { bundle_cnsic "$1"; local r="$1/repository"; put "$1/observations/file/locator" CONTRIBUTING.md; put "$1/observations/file/checksum" "$(cksum "$r/CONTRIBUTING.md" | awk '{print $1 " " $2}')"; put "$1/observations/graph/locator" go.mod; put "$1/observations/graph/checksum" "$(cksum "$r/go.mod" | awk '{print $1 " " $2}')"; put "$1/facts/declaration/adapter" gentle-ai-go-v1; put "$1/facts/tool/adapter" gentle-ai-go-v1; put "$1/bindings/unit/context/executable" go; put "$1/bindings/unit/scope" module-root; put "$1/bindings/unit/signature-coverage" .; list "$1/bindings/unit/context/argv" test ./...; sync_facts "$1"; }
 tamper_fields() { local copy=$1; shift; local field; for field; do put "$copy/records/000/$field" replay; done; }
attestation_identity() { local d=$1 k; for k in adapter-bytes-digest adapter-id adapter-version argv-digest binding-id claim-kind evidence-fact-id executable input-digest method observation-digest observation-id schema scope source-locator status; do printf '%s=%s\n' "$k" "$(get "$d/$k")"; done; }
refresh_order() { local b=$1 g d; local -a ids=(); for g in observations facts attestations bindings rows questions; do for d in "$b/$g"/*; do [ -d "$d" ] && ids+=("$(get "$d/id")"); done; done; mapfile -t ids < <(printf '%s\n' "${ids[@]}" | LC_ALL=C sort); list "$b/record-order" "${ids[@]}"; }
write_cp_hook() {
  mkdir -p "$TMP/hook-bin"
  cat > "$TMP/hook-bin/cp" <<'EOF'
#!/bin/sh
for x; do
  [ "${DRIFT_META-}" = "$x" ] && { /bin/cp "$@"; printf drift > "$DRIFT_META_FILE"; : > "$DRIFT_META_MARK"; exit; }
  [ "${DRIFT_RECORDS-}" = "$x" ] && { /bin/cp "$@"; printf drift > "$DRIFT_RECORD_FILE"; : > "$DRIFT_RECORDS_MARK"; exit; }
  [ "${DRIFT_EVIDENCE-}" = "$x" ] && { /bin/cp "$@"; printf drift >> "$DRIFT_EVIDENCE"; : > "$DRIFT_EVIDENCE_MARK"; exit; }
done
exec /bin/cp "$@"
EOF
  chmod +x "$TMP/hook-bin/cp"
}
load_structure_fixture; extract_block details adapter-gate "$TMP/details"; extract_block pi adapter-gate "$TMP/pi"; extract_block details adapter-records "$TMP/records-run"; extract_block details validator "$TMP/validator"; payload "$TMP/details" "$TMP/details-payload"; payload "$TMP/pi" "$TMP/pi-payload"
cmp -s "$TMP/details" "$TMP/pi" && [ -s "$TMP/details" ] && ok 'Details and Pi gate bytes match' || no 'missing or divergent gate'
cmp -s "$TMP/validator" "$TMP/details-payload" && cmp -s "$TMP/validator" "$TMP/pi-payload" && ok 'embedded Unit1A payloads have byte parity' || no 'embedded Unit1A payload drift'
b="$TMP/base"; bundle_cnsic "$b"; REC="$TMP/records"; "$TMP/validator" "$b" >/dev/null && "$TMP/records-run" records "$b" "$REC" || { no 'valid detached CNSIC fixture'; exit 1; }; RUN="$TMP/details"; OUT="$TMP/semantic-receipt"
