ln -s "$b" "$TMP/candidate-symlink"; ! reject "$RUN" gate "$TMP/candidate-symlink" "$REC" "$TMP/candidate-symlink-out" && ok 'symlinked candidate directory blocks replay' || no 'symlinked candidate directory was accepted'
mkdir "$TMP/candidate-real"; cp -a "$b" "$TMP/candidate-real/bundle"; ln -s "$TMP/candidate-real" "$TMP/candidate-parent"; ! reject "$RUN" gate "$TMP/candidate-parent/bundle" "$REC" "$TMP/candidate-parent-out" && ok 'symlinked candidate path component blocks replay' || no 'symlinked candidate path component was accepted'
cp -a "$b" "$TMP/root-symlink"; rebase_root "$TMP/root-symlink"; mv "$TMP/root-symlink/repository" "$TMP/root-symlink/real"; ln -s real "$TMP/root-symlink/repository"; ! reject "$RUN" gate "$TMP/root-symlink" "$REC" "$TMP/root-symlink-out" && ok 'symlinked repository root blocks replay' || no 'symlinked repository root was accepted'
cp -a "$b" "$TMP/locator-symlink"; rebase_root "$TMP/locator-symlink"; mkdir "$TMP/locator-symlink/repository/real"; mv "$TMP/locator-symlink/repository/AGENTS.md" "$TMP/locator-symlink/repository/real/AGENTS.md"; ln -s real "$TMP/locator-symlink/repository/link"; put "$TMP/locator-symlink/observations/file/locator" link/AGENTS.md; put "$TMP/locator-symlink/observations/file/checksum" "$(cksum "$TMP/locator-symlink/repository/real/AGENTS.md" | awk '{print $1 " " $2}')"; sync_facts "$TMP/locator-symlink"; ! reject "$RUN" gate "$TMP/locator-symlink" "$REC" "$TMP/locator-symlink-out" && ok 'symlinked evidence locator blocks replay' || no 'symlinked evidence locator was accepted'
