cp -a "$REC" "$TMP/extra"; cp -a "$TMP/extra/records/000" "$TMP/extra/records/009"; put "$TMP/extra/records/009/evidence-fact-id" extra; ! reject "$RUN" gate "$b" "$TMP/extra" "$TMP/extra-out" && ok 'extra record blocks' || no 'extra record was accepted'
