cp -a "$REC" "$TMP/codegraph-scope"; put "$TMP/codegraph-scope/records/000/scope" project-root; ! reject "$RUN" gate "$b" "$TMP/codegraph-scope" "$TMP/codegraph-scope-out" && ok 'CodeGraph cannot widen scope' || no 'CodeGraph scope widening was accepted'
cp -a "$REC" "$TMP/unknown"; put "$TMP/unknown/records/000/status" unknown; ! reject "$RUN" gate "$b" "$TMP/unknown" "$TMP/unknown-out" && ok 'unknown non-skip obligation blocks' || no 'unknown obligation was accepted'
