cp -a "$b" "$TMP/narrow"; put "$TMP/narrow/bindings/unit/signature-coverage" tests; ! reject "$RUN" gate "$TMP/narrow" "$REC" "$TMP/narrow-out" && ok 'narrow conservative scope mismatch blocks' || no 'narrow scope mismatch was accepted'
