find "$b" -type f -exec cksum {} + | LC_ALL=C sort > "$TMP/candidate-pre"; INTEGRATED="$TMP/integrated"; if "$RUN" integrate "$b" "$REC" "$INTEGRATED" && [ -d "$INTEGRATED" ]; then ok 'integration reconstructs a complete staged bundle'; else no 'integration reconstructs a complete staged bundle'; fi
